namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;
    private readonly Lock _lock = new();

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious traditional Italian pizza with fresh basil and mozzarella.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps =
                [
                    "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                    "Stretch the dough into a 12-inch circle on a floured surface.",
                    "Spread crushed tomatoes evenly over the dough, leaving a 1-inch border.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10-12 minutes until the crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil before serving."
                ],
                TotalRatings = 12, RatingSum = 52
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a rich, creamy tomato-based curry sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps =
                [
                    "Marinate chicken in yogurt, garam masala, cumin, and turmeric for at least 1 hour.",
                    "Grill or broil marinated chicken until lightly charred.",
                    "Sauté diced onion, garlic, and ginger in oil until softened.",
                    "Add tomato sauce and remaining spices; simmer for 15 minutes.",
                    "Stir in heavy cream, then add the grilled chicken pieces.",
                    "Simmer for 10 more minutes and serve over basmati rice."
                ],
                TotalRatings = 8, RatingSum = 38
            },
            new Recipe
            {
                Id = 3, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef tacos with fresh toppings in crispy shells.",
                Ingredients = ["Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning", "Onion"],
                Steps =
                [
                    "Brown ground beef with diced onion in a skillet over medium-high heat.",
                    "Add taco seasoning and water according to package directions; simmer 5 minutes.",
                    "Warm taco shells in the oven at 325°F for 5 minutes.",
                    "Shred lettuce, dice tomatoes, and grate cheese.",
                    "Fill each shell with seasoned beef and top with desired toppings.",
                    "Serve immediately with sour cream on the side."
                ],
                TotalRatings = 15, RatingSum = 60
            },
            new Recipe
            {
                Id = 4, Title = "Pad Thai", Category = "Thai",
                Description = "Classic Thai stir-fried rice noodles with shrimp, peanuts, and lime.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Fish sauce", "Tamarind paste", "Lime", "Sugar"],
                Steps =
                [
                    "Soak rice noodles in warm water for 30 minutes, then drain.",
                    "Mix tamarind paste, fish sauce, and sugar to make the sauce.",
                    "Stir-fry shrimp in oil until pink; push to the side and scramble eggs.",
                    "Add drained noodles and sauce; toss to coat evenly.",
                    "Add bean sprouts and green onions; stir-fry for 1-2 minutes.",
                    "Serve topped with crushed peanuts and lime wedges."
                ],
                TotalRatings = 10, RatingSum = 45
            },
            new Recipe
            {
                Id = 5, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "A creamy Roman pasta dish made with eggs, cheese, pancetta, and black pepper.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Parmesan", "Black pepper", "Salt"],
                Steps =
                [
                    "Cook spaghetti in salted boiling water until al dente; reserve 1 cup pasta water.",
                    "Crisp pancetta in a large skillet over medium heat.",
                    "Whisk together eggs, grated Pecorino, Parmesan, and plenty of black pepper.",
                    "Drain pasta and add to the skillet with pancetta (off heat).",
                    "Pour egg mixture over hot pasta and toss rapidly, adding pasta water as needed.",
                    "Serve immediately with extra cheese and pepper."
                ],
                TotalRatings = 20, RatingSum = 92
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and zesty avocado dip — perfect as a snack or topping.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt", "Garlic"],
                Steps =
                [
                    "Halve and pit 3 ripe avocados; scoop flesh into a bowl.",
                    "Mash with a fork to desired consistency.",
                    "Stir in diced onion, tomato, jalapeño, minced garlic, and chopped cilantro.",
                    "Add lime juice and salt to taste.",
                    "Serve immediately with tortilla chips."
                ],
                TotalRatings = 6, RatingSum = 27
            },
            new Recipe
            {
                Id = 7, Title = "Butter Chicken", Category = "Indian",
                Description = "Mild, buttery tomato curry with tender chicken — a crowd favorite.",
                Ingredients = ["Chicken thighs", "Butter", "Tomato purée", "Heavy cream", "Garam masala", "Cumin", "Garlic", "Ginger", "Chili powder", "Fenugreek leaves"],
                Steps =
                [
                    "Marinate chicken in yogurt and spices for at least 2 hours.",
                    "Sear chicken in butter until browned on all sides.",
                    "In the same pan, sauté garlic and ginger; add tomato purée and spices.",
                    "Simmer sauce for 20 minutes until thickened.",
                    "Add cream and dried fenugreek leaves; stir in the chicken.",
                    "Simmer 10 minutes and serve with naan bread."
                ],
                TotalRatings = 14, RatingSum = 64
            },
            new Recipe
            {
                Id = 8, Title = "Green Curry", Category = "Thai",
                Description = "Aromatic Thai green curry with vegetables and coconut milk.",
                Ingredients = ["Green curry paste", "Coconut milk", "Chicken breast", "Bamboo shoots", "Thai basil", "Fish sauce", "Sugar", "Bell pepper", "Eggplant"],
                Steps =
                [
                    "Heat a splash of coconut cream in a wok until it separates.",
                    "Fry green curry paste for 1-2 minutes until fragrant.",
                    "Add sliced chicken and stir until coated with paste.",
                    "Pour in coconut milk; add sliced eggplant, bamboo shoots, and bell pepper.",
                    "Season with fish sauce and sugar; simmer 15 minutes.",
                    "Stir in Thai basil and serve over jasmine rice."
                ],
                TotalRatings = 9, RatingSum = 40
            },
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        lock (_lock)
        {
            return _recipes.Select(r => r.Category).Distinct().Order().ToList();
        }
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetById(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;

        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null)
            {
                recipe.TotalRatings++;
                recipe.RatingSum += stars;
            }
        }
    }

    public Recipe AddRecipe(string title, string ingredients, string steps)
    {
        lock (_lock)
        {
            var recipe = new Recipe
            {
                Id = _nextId++,
                Title = title.Trim(),
                Category = "Community",
                Description = "A community-submitted recipe.",
                Ingredients = ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
                Steps = steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
            };
            _recipes.Add(recipe);
            return recipe;
        }
    }
}

