@page "/category/{CategoryName}"
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>
<p><a href="/">← Back to all categories</a></p>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text text-muted">@recipe.Description</p>
                        <p>
                            <span class="text-warning">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                                }
                            </span>
                            <small class="text-muted">(@recipe.TotalRatings ratings)</small>
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<RecipeHub.Models.Recipe> recipes = [];

    protected override void OnInitialized()
    {
        recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeHub.Services.RecipeService RecipeService

@if (recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeHub</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="/">← Back to Home</a>
}
else
{
    <PageTitle>@recipe.Title — RecipeHub</PageTitle>

    <p><a href="category/@recipe.Category">← Back to @recipe.Category recipes</a></p>

    <h1>@recipe.Title</h1>
    <p class="lead text-muted">@recipe.Description</p>
    <span class="badge bg-secondary">@recipe.Category</span>

    <hr />

    <div class="row">
        <div class="col-md-4">
            <h3>🧾 Ingredients</h3>
            <ul class="list-group list-group-flush">
                @foreach (var ingredient in recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>
        <div class="col-md-8">
            <h3>👩‍🍳 Steps</h3>
            <ol>
                @foreach (var step in recipe.Steps)
                {
                    <li class="mb-2">@step</li>
                }
            </ol>
        </div>
    </div>

    <hr />

    <h3>⭐ Rate this Recipe</h3>
    <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@inject RecipeHub.Services.RecipeService RecipeService

<div>
    <div style="font-size: 2rem; cursor: pointer; user-select: none;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => Rate(star)"
                  @onmouseover="() => hovered = star"
                  @onmouseout="() => hovered = 0"
                  style="color: @(star <= DisplayStars ? "#ffc107" : "#e0e0e0"); transition: color 0.15s;">
                ★
            </span>
        }
    </div>

    @if (submitted)
    {
        <div class="alert alert-success mt-2 py-1 px-2 d-inline-block">
            Thanks for rating! You gave @lastRating star(s).
        </div>
    }

    @{
        var recipe = RecipeService.GetById(RecipeId);
    }
    @if (recipe is not null && recipe.TotalRatings > 0)
    {
        <p class="text-muted mt-1 mb-0">
            Average: @recipe.AverageRating.ToString("0.0") / 5 (@recipe.TotalRatings ratings)
        </p>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int hovered;
    private int lastRating;
    private bool submitted;

    private int DisplayStars => hovered > 0 ? hovered : lastRating;

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        lastRating = stars;
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeHub.Services.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>
